SELECT GROUP_CONCAT(author || ' (' || date || '): ' || COALESCE(content, '') || ' - ' || COALESCE(notes, ''), '
---
') as all_revisions FROM protocol_revisions;

SELECT GROUP_CONCAT(full_name || ' (<' || email || '>) - ' || COALESCE(role, ''), '
---
') as all_contacts FROM lab_contacts;

SELECT GROUP_CONCAT(author || ' (' || date || '): ' || COALESCE(content, '') || ' - ' || COALESCE(notes, ''), CHAR(10) || '---' || CHAR(10) as safe_revisions 
FROM protocol_revisions 
WHERE revision_id != 402 AND content NOT LIKE '%postgresql%';

